UPDATE companies SET description='Auto Vehicle Parts LLC, doing business as Auveco, is headquartered in Cold Spring, Kentucky. The current limited liability company was formed in 2023, but the Auveco brand has been manufacturing and distributing specialty automotive and industrial fasteners for over 100 years. No founder names or ownership structure are disclosed in public materials.

The company supplies what it describes as the largest selection of body hardware and specialty fasteners, including clips, retainers, and related components. Its product portfolio encompasses monthly new item releases, unit boxes, bulk quantities, and the proprietary AuvecoPaks—single-price small bags designed for retail displays—as well as assortment kits and merchandising aids. Auveco also provides technical support and product identification services to help customers locate the correct part.

Auveco serves the automotive and industrial sectors, with a focus on the body hardware industry. The company’s customer service team operates Monday through Friday, Eastern Time, handling inquiries on availability, pricing, delivery, and technical specifications.

Auveco cites four core values as differentiators: a customer-first approach, a sense of urgency that drives same-day shipping on stocked items, transparency in product information and processes, and continuous improvement fueled by customer feedback. The company states its goal remains the same as it was a century ago: complete customer satisfaction.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Fastener manufacturing", "Clip manufacturing", "Body hardware manufacturing", "Distribution", "Same-day shipping", "Technical support", "Product identification", "Custom packaging (AuvecoPaks)", "Assortment kitting", "Merchandising program management", "Monthly new product introduction"], "industries": ["Automotive", "Industrial", "Body hardware"], "materials": [], "equipment": [], "volume": "", "lead_time": "Same-day shipping for in-stock items", "tolerances": "", "built_on": ["Same-day shipping on in-stock items", "Dedicated technical support and product identification team", "Monthly new product introductions", "AuvecoPaks single-price retail packaging program", "Transparency in product specifications and processes"], "facts_used": ["Company name Auto Vehicle Parts LLC (Auveco) -> db", "Headquarters Cold Spring, Kentucky -> db", "Founded year 2023 -> db", "Over 100 years history manufacturing and distributing fasteners -> /about-us", "Manufacturing and distributing specialty automotive and industrial fasteners -> /about-us", "Largest selection of body hardware and specialty fasteners -> /about-us", "Monthly new product introductions -> /about-us", "Product offerings: unit boxes, bulk quantities, AuvecoPaks, assortments, merchandising aids -> /about-us", "Technical support and product identification team -> /about-us", "Same-day shipping on stocked items (core value) -> /about-us", "Core values: customer focus, urgency, transparency, continuous improvement -> /about-us", "Customer service hours and contact -> /about-us", "Goal of complete customer satisfaction -> /about-us"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "For over 100 years, Auto-Vehicle Parts LLC (Auveco) has been manufacturing and distributing specialty automotive and industrial fasteners.", "founded_year": "2023", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='auto-vehicle-parts-llc' AND approved AND profile IS NULL;
