employee_count": "over 35", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='automotive-supply-center' AND approved AND profile IS NULL;
UPDATE companies SET description='Founded in 1981 as a family-owned business in Baltimore, Maryland, Avalon Industries operates two distinct divisions under common ownership. The company began as a manufacturer of soft-sided carrying cases and has since expanded to include a promotional products division.

The manufacturing division produces soft-sided carrying cases, bags, totes, and molded laminate cases designed to hold and transport supplies and equipment for commercial and military applications. The second division, Avalon Promotional Products, functions as an advertising specialties distributor, supplying personalized apparel, uniforms, and branded merchandise for corporate and organizational identity programs.

Avalon’s customer base spans the U.S. defense department, first-responder agencies, public schools, municipal governments, youth sports leagues, and the broader commercial marketplace. Both divisions have supplied these sectors for several years, providing custom carrying solutions and branded promotional items tailored to each end user.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Soft-sided carrying case manufacturing", "Bag and tote production", "Molded laminate case fabrication", "Promotional product distribution", "Apparel personalization and embroidery", "Uniform supply"], "industries": ["Defense", "First responders", "Education", "Government", "Youth sports", "Commercial"], "materials": [], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": [], "facts_used": ["Founded in 1981 -> db", "Family-owned -> page /", "Two divisions: manufacturer of soft-sided carrying cases, bags, totes, molded laminate cases; and promotional products distributor -> page /", "Products: soft-sided carrying cases, bags, totes, molded laminate cases for commercial and military applications -> page /", "Promotional products: personalized apparel, uniforms, merchandise -> page /", "Customers: defense department, first responders, schools, cities, towns, youth sports leagues, commercial marketplace -> page /", "Headquarters: Baltimore, Maryland -> db"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "a manufacturer known as ... soft sided carrying cases, bags, totes and molded laminate cases for commercial and military applications", "founded_year": "1981", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": ["Family-owned"]}'::jsonb, updated_at=now() WHERE slug='avalon-industries' AND approved AND profile IS NULL;
UPDATE companies SET description='Avon Food Company operates from a 55,000-square-foot facility in Stoughton, Massachusetts. The business was founded in 2002 by Stephen and Heidee Anastos as a small family-run operation focused on sauces, dressings, and marinades. Today, the company is led by their son, Michael Anastos, who has expanded the operation while maintaining its family-owned character.

The company manufactures liquid and dry food products, including sauces, dressings, marinades, and custom spice blends. Its services span research and development, liquid manufacturing, spice blending, storage and delivery, quality and compliance, and full private-label manufacturing. Four dedicated production lines handle a range of viscosities and formats: an electromagnetic filler for high-speed liquid filling, pressure overflow and piston fillers for versatile sauces and dressings, an auger filler for dry spices, and a line for 5-gallon pail and bag-in-box packaging. The facility employs 35-plus people and produces more than 300 distinct items.

Avon Food serves established brands and startups across North America, providing private-label manufacturing and co-packing for the specialty food, sauce, dressing, marinade, and spice-blend categories. Customers include wholesale and private-label partners who rely on the company''s nationwide shipping and regional delivery options.

The Anastos family started the business with a vision of creating exceptional products made with care and consistency. The company emphasizes its SQF-certified, HACCP-compliant processes, scalable production from small batches to large runs, and a partnership-first approach that includes in-house recipe development and ingredient sourcing.', certifications=ARRAY['HACCP','SQF']::text[], profile='{"capabilities": ["Research & Development", "Liquid Manufacturing", "Spice Blending", "Storage & Delivery", "Quality & Compliance", "Private Label Manufacturing", "Custom Formulation", "Flavor Testing", "Ingredient Sourcing", "Scalability Testing", "Packaging", "Labeling", "Sauce Manufacturing", "Dressing Manufacturing", "Marinade Manufacturing", "Spice Blend Manufacturing", "Hot Fill", "Cold Fill", "Electromagnetic Filling", "Pressure Overflow Filling", "Piston Filling", "Auger Filling", "Pail Filling", "Bag-in-Box Filling"], "industries": ["Food Manufacturing", "Private Label", "Sauces", "Dressings", "Marinades", "Spice Blends", "Wholesale"], "materials": [], "equipment": ["Electromagnetic filler", "Pressure overflow filler", "Piston filler", "Auger filler", "5-gallon pail filler", "Bag-in-box filler"], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["SQF-certified facility with HACCP compliance", "Family-owned with second-generation leadership", "Four specialized production lines for liquid and dry products", "In-house R&D for custom formulation and recipe development", "Nationwide shipping and flexible pickup options"], "facts_used": ["Founded in 2002 by Stephen and Heidee Anastos -> /about-us", "Now led by son Michael Anastos -> /about-us", "Headquartered in Stoughton, Massachusetts -> /about-us", "55,000 square foot facility -> /about-us", "SQF-certified and HACCP compliant -> / and /about-us", "35+ employees -> / (Hardworking People 35+)", "300+ items produced -> / (Items Produced 300+)", "Services: Research & Development, Liquid Manufacturing, Spice Blending, Storage & Delivery, Quality & Compliance, Private Label -> /", "Products: sauces, dressings, marinades, spice blends -> /about-us", "Equipment: electromagnetic filler, pressure overflow filler, piston filler, auger filler, 5-gallon pail filler, bag-in-box filler -> /about-us", "Family-owned -> / and /about-us", "Nationwide shipping -> /about-us", "In-house R&D for custom formulation -> /about-us"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "Avon Food specializes in liquid and dry food production, including sauces, dressings, marinades, and spice blends.", "founded_year": "2002", "employee_count": "35+", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": ["Family-owned"]}'::jsonb, updated_at=now() WHERE slug='avon-food-company' AND approved AND profile IS NULL;
UPDATE companies SET description='Avon Lake Sheet Metal Company, Inc. was founded in 1953 by George Wightman and Carl Wetzig Sr. in a one-car garage in Avon Lake, Ohio, about 25 miles west of Cleveland. The business has remained family-owned through three generations, with second-generation owners Carl Wetzig Jr. and Gary Wightman now the company.

The company operates a 32,000-square-foot facility on a five-acre industrial site, equipped with CNC laser cutting (Trumpf 4 kW fiber laser), CNC plasma cutting, CNC press brake forming, CNC panel folding, plate rolling, and a range of welding processes including pulsed MIG, TIG, stick, and flux-core. In-house capabilities cover sheet metal and structural fabrication, assembly of mechanical components and modules, finishing such as painting and laser etching, and 3D modeling using Autodesk Inventor. The shop also provides industrial contracting services, including equipment installation, plant maintenance, project management, and coordination drawings.

Avon Lake Sheet Metal serves industries such as automotive, steel and foundry, chemical, plastics, construction, food processing, general manufacturing, retail, education, and health care. Customers include industrial mills, foundries, food processing companies, and medical groups, with projects ranging from custom machine guarding and HVAC duct systems to dust collection and pneumatic conveying installations.

The founders built the business on honesty and hard work, values that remain central today. The company emphasizes a combined fabrication-and-installation model to reduce the burden of multiple contracts, maintains a union workforce with AWS-certified welders, and has earned SMACNA Zero Injury Awards in multiple years, reflecting a long-standing safety focus.', certifications=ARRAY['SMACNA Zero Injury Award (2015, 2017, 2018, 2020, 2022)','AWS Certified Welders','Ohio License #18015','OHIO BWC Drug-Free Workplace']::text[], profile='{"capabilities": ["Sheet metal fabrication", "Structural fabrication", "CNC laser cutting", "CNC plasma cutting", "CNC shearing", "CNC press brake forming", "CNC panel folding", "Sheet and plate rolling", "Pulsed MIG welding", "MIG welding", "Flux core welding", "Stick welding", "TIG welding", "Spot welding", "Field welding", "Assembly of mechanical components", "Assembly of modules or skids", "Laser etching", "Painting", "Glass beading", "Grinding and polishing", "3D modeling and design", "Coordination drawings", "Project management"], "industries": ["Automotive", "Steel and Foundry", "Chemical", "Plastics", "Construction", "Food Processing", "General Manufacturing", "Retail", "Education", "Health Care"], "materials": ["Sheet metal", "Structural steel"], "equipment": ["Trumpf TruLaser 2030 4,000 Watt Fiber Laser Cutting Center", "Trumpf TruBend 2100 B35 Press Brake", "Lockformer Vulcan 2900 Dual Table CNC Plasma Cutter", "Wysong \u00bc\u201d x 10 Hydraulic Shear CNC Front and Rear Gauging", "Wysong 12\u2019 x 175 Ton Hydraulic Press Brake CNC Gauging", "Fasti FP60 \u00bc\u201d x 126\u201d CNC Panel Former", "GEKA Hydraulic Ironworker", "Ercolina Tube Bender", "Ercolina Tube Notcher", "2 Power Plate Rolls", "14\u2019 x 26\u2019 Paint Booth with Mix Room", "6 Sheet Metal Roll Formers", "8,000 # Gantry Cranes", "2,000 # Bridge Crane with Vacuum Sheet Lifter", "FMS Mitering Bandsaw", "Hougen \u2013 Nitto Magnetic Drills"], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Family-owned and operated since 1953", "32,000 sq ft facility with Trumpf fiber laser and CNC forming equipment", "Union shop with AWS-certified welders and SMACNA Zero Injury Award recognition", "Combined fabrication, installation, and plant maintenance services under one contract", "In-house 3D modeling and coordination drawing capabilities"], "facts_used": ["Founded 1953 -> /about-us", "Founders George Wightman and Carl Wetzig Sr. -> /about-us", "Family-owned through three generations -> /about-us", "32,000 sq ft facility on 5-acre site -> /about-us", "Trumpf TruLaser 2030 4 kW fiber laser -> /about-us", "AWS certified welders -> /about-us", "SMACNA Zero Injury Awards 2015,2017,2018,2020,2022 -> /about-us", "Industries served: Automotive, Steel and Foundry, Chemical, Plastics, Construction, Food Processing, General Manufacturing, Retail, Education, Health Care -> /about-us", "Combined fabrication and installation services -> / (homepage)", "Machine guarding fabrication and installation -> /capabilities", "HVAC duct fabrication and installation -> /capabilities"], "company_type": "Contract manufacturer / job shop", "makes_products": "yes", "type_evidence": "Custom Fabrication & Contracting Services", "founded_year": "1953", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": ["Family-owned"]}'::jsonb, updated_at=now() WHERE slug='avon-lake-sheet-metal-company-inc' AND approved AND profile IS NULL;
UPDATE companies SET description='Axial Medical operates a 40,000-square-foot facility in Warminster, Pennsylvania, just outside Philadelphia. The current headquarters was custom-built in 2014 around the needs of the medical device industry.

The shop specializes in precision machining and assembly for medical devices, running over 60 five-axis CNC mills—including Mazak, Haas, and Chiron machines—alongside Fanuc wire EDMs capable of 72-hour unmanned runs. In-line gun drilling serves cannulated products, while high-speed five-axis mills enable single-operation machining to tolerances of ±0.0001 inch. Optical and video inspection systems feed electronic data for statistical process control. The company also offers automated robotic cells, environmentally controlled assembly areas, and full validation of all in-house processes.

Axial serves medical device manufacturers, supporting projects from prototype through full-scale production. Its vendor-managed inventory programs and emphasis on risk mitigation cater to OEMs requiring regulated, traceable supply chains. The company highlights expertise in expandable implant production and complex assemblies.

The firm differentiates itself through its ISO 13485:2016 certification, FDA registration, and a continuous-improvement culture focused on part-per-bar yield optimization. Its "Made For Life" tagline reflects a commitment to delivering regulated components on time and on budget.', certifications=ARRAY['ISO 13485:2016','FDA Registered']::text[], profile='{"capabilities": ["4-axis CNC milling", "5-axis CNC milling", "Wire EDM (Fanuc, 72-hour unmanned)", "In-line gun drilling", "Assembly and finishing", "Optical/video inspection", "Automation and robotics integration", "Vendor managed inventory (VMI) programs", "Full process validation", "Electronic inspection data for SPC", "Continuous improvement / risk mitigation", "High-tolerance machining (\u00b10.0001 in)", "Single-operation machining on high-speed 5-axis mills", "Complex assembly", "Expandable implant production", "Part-per-bar yield optimization"], "industries": ["Medical Device Manufacturing"], "materials": [], "equipment": ["Mazak milling machines", "Haas milling machines", "Chiron milling machines", "Fanuc wire EDMs", "High-speed 5-axis CNC mills", "Optical/video inspection systems", "In-line gun drilling equipment", "Automation and robotic cells", "Environmentally controlled assembly areas"], "volume": "", "lead_time": "", "tolerances": "\u00b10.0001 in", "built_on": ["ISO 13485:2016 certified and FDA registered", "Full validations for all in-house capabilities", "Automation and robotics integrated for productivity", "Electronic inspection data enabling real-time SPC analysis", "Vendor-managed inventory programs", "72-hour unmanned production on Fanuc wire EDMs", "In-line gun drilling for cannulated parts", "\u00b10.0001 inch tolerance capability"], "facts_used": ["Headquarters in Warminster, Pennsylvania -> db", "40,000-square-foot facility custom-built in 2014 -> /about", "Over 60 five-axis CNC machines -> /about", "Mazak, Haas, Chiron milling machines -> /about, /", "Fanuc wire EDMs with 72-hour unmanned