UPDATE companies SET description='Axiom Manufacturing operates from Richardson, Texas, where it has been building electronic assemblies since 1992. The company does business as Axiom Manufacturing under the Axent Manufacturing entity, though founder names and ownership structure are not disclosed publicly.

The shop focuses on printed circuit board assembly — both surface-mount and through-hole with automated optical inspection — alongside custom RF engineering that covers schematic capture, layout, and integration up to 40 GHz. It also provides full box-build electromechanical assembly and runs environmental, functional, and reliability testing to military standards. Over three decades the operation has shipped more than one million units to over five hundred customers.

Customers span aerospace and defense programs needing mission-critical aviation and space systems, industrial firms requiring ruggedized electronics for harsh environments, medical device makers who need FDA-compliant production, and telecom companies deploying high-frequency wireless infrastructure.', certifications=ARRAY[]::text[], profile='{"capabilities": ["PCB Assembly (surface mount, through-hole, automated optical inspection)", "RF Engineering (custom RF circuit design, schematic capture, layout, testing, integration up to 40 GHz)", "Box Build Assembly (electromechanical assembly, full testing)", "Quality Testing (environmental, functional, reliability testing to military standards)"], "industries": ["Aerospace & Defense", "Industrial", "Medical", "Telecom"], "materials": [], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["98% on-time delivery rate", "RF design and test capability up to 40 GHz", "FDA-compliant manufacturing for medical devices", "Environmental and reliability testing to military standards", "30+ years of continuous operation"], "facts_used": ["Founded 1992 -> page ''/''", "Headquarters Richardson, Texas -> page ''/''", "Capabilities: PCB Assembly, RF Engineering, Box Build, Quality Testing -> page ''/''", "Industries: Aerospace & Defense, Industrial, Medical, Telecom -> page ''/''", "98% on-time delivery, 500+ customers, 1M+ units delivered -> page ''/''", "RF up to 40 GHz -> page ''/''", "FDA-compliant medical manufacturing -> page ''/''", "Military standards testing -> page ''/''", "DBA Axent Manufacturing -> page ''/''"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "Precision Electronics Manufacturing & Engineering Services", "founded_year": "1992", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='axiom-manufacturing' AND approved AND profile IS NULL;
UPDATE companies SET description='Axles Plus operates from Beebe, Arkansas, where the company moved in 2017 after establishing the Axles Plus brand in Ward in 2015. The business traces its roots to 1979 when Custom Tool & Die, Inc. began in a small garage; it incorporated in April 1980 and has been based on Highway 5 near Cabot since 1982. Now in its third generation, the company remains family owned and operated.

The Cabot facility houses a full metal fabrication, tool and die, and manufacturing plant where production centers on CNC machining, laser cutting, metal fabrication, stamping, and custom manufacturing. At the Beebe location the team assembles trailer axles from scratch, prepares trucks for in‑state and out‑of‑state delivery, and runs a retail showroom stocked with tongue hitches, trailer jacks, axle bearings, LED clearance lights, brake lights, and bulk tires and wheels.

Axles Plus serves the trailer market broadly, building axles and components for equipment trailers, travel trailers, horse trailers, and other trailer types. Customers include both commercial trailer builders and individual owners who purchase parts directly from the showroom.

The company emphasizes that customer service and quality are non‑negotiable, positioning its American‑made, family‑run operation as a differentiator in a market where it says service still matters.', certifications=ARRAY[]::text[], profile='{"capabilities": ["CNC machining", "laser cutting", "metal fabrication", "stamping", "custom manufacturing", "tool and die", "axle assembly", "retail sales"], "industries": ["Equipment trailers", "Travel trailers", "Horse trailers", "General trailer market", "Retail trailer parts"], "materials": ["Steel (4 gauge)"], "equipment": ["CNC machining centers", "Laser cutting systems"], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Third-generation family ownership", "In-house manufacturing from raw material to finished axle assembly", "Retail showroom at Beebe location for direct customer access", "CNC machining, laser cutting, and stamping under one roof", "Customer service emphasized as top priority"], "facts_used": ["Founded 1979 in garage; incorporated April 1980 -> db, /", "Family-owned third generation -> /", "Locations: Cabot since 1982, Ward 2015, Beebe 2017 -> /", "Processes: CNC machining, laser cutting, metal fabrication, stamping, custom manufacturing -> db, /", "Products: trailer axles, components, accessories, hardware kits, spring latch assemblies -> db, /", "Industries: equipment trailers, travel trailers, horse trailers -> /", "Retail showroom at Beebe -> /", "Material: 4 gauge steel for shackle straps -> db", "Company type: manufacturing company -> /"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "Custom Tool & Die, Inc. dba Axles Plus is a third generation, family owned and operated manufacturing company", "founded_year": "1979", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": ["Family-owned"]}'::jsonb, updated_at=now() WHERE slug='axles-plus' AND approved AND profile IS NULL;
UPDATE companies SET description='Axon Medical Technologies operates from New Cumberland, Pennsylvania, where it was founded in 2003 by Michael Zarreii. Zarreii, who serves as chief executive and chief scientific officer, began the venture as a philanthropic effort to explore the link between the brain''s involuntary sensory functions and cognition. His background spans electronics engineering, controls engineering, and continuing medical education in neurology at NYU''s School of Medicine.

The company designs and manufactures two primary platforms in an FDA-registered U.S. facility: ECAT, a point-of-care multi-screening system that runs automated assessments for depression, anxiety, cognitive decline, TBI, PTSD, and ADHD; and Intellig-EYES, a lightweight headgear that captures 140 parameters of cranial nerve performance through advanced pupillometry. Tests include Trail Making A and B, GPCOG, MMSE, CAPS-5, and rapid sideline concussion screening. ECAT integrates with Epic, Cerner, and other EMRs, and the company employs a leasing model with per-scan billing supported by CPT codes for Medicare and private insurance reimbursement.

Axon Medical serves primary care clinics, military treatment facilities, and sports medicine programs. The U.S. Army has funded a four-year study to integrate both platforms into battlefield and hospital protocols, and the NCAA''s chief medical officer sits on the advisory board alongside Army medical research colonels and university physicians. The technology addresses depression, anxiety, cognitive impairment, PTSD, concussions, and attention disorders.

Zarreii''s motivation traces to the loss of his daughter Samira, after whom Intellig-EYES is named. The company invested 19 years and millions of dollars without government grants to develop non-invasive, objective diagnostics that generate clear reports in a single extended visit. Multiple patents have been issued with more pending, covering optics, stimuli generation, and measurement standards for autonomic nervous system assessment.', certifications=ARRAY['FDA-REGISTERED']::text[], profile='{"capabilities": ["Point-of-care multi-screening assessments", "Automated cognitive testing (Trail Making A/B, GPCOG, MMSE)", "PTSD assessment (CAPS-5)", "Automated pupillometry", "Concussion screening (sideline test)", "Cognitive alertness testing", "Neurological performance measurement (Intellig-EYES)", "EMR integration (Epic, Cerner)", "Clinical documentation generation", "Device leasing and per-scan billing"], "industries": ["Primary care / family practice", "Military / U.S. Army", "Sports medicine / NCAA", "Neurology / cognitive health", "Mental health", "Traumatic brain injury / concussion management"], "materials": [], "equipment": ["ECAT platform", "Intellig-EYES headgear"], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Designed and manufactured in the USA in an FDA-registered facility", "ECAT exempt from 510(k) premarket notification", "Leasing model with nominal device fee and per-scan charges", "CPT codes for Medicare and insurance reimbursement", "Advanced pupillometry measuring cranial nerves II, III, VI, VIII"], "facts_used": ["Founded 2003 by Michael Zarreii -> /about", "Headquarters New Cumberland, Pennsylvania -> db", "FDA-registered facility, manufactured in USA -> /", "ECAT platform and Intellig-EYES headgear -> /, /about", "Automated tests: Trail Making A/B, GPCOG, MMSE, CAPS-5, pupillometry, sideline test, cognitive alertness -> /", "EMR integration with Epic, Cerner -> /", "Leasing model with per-scan billing and CPT codes -> /about", "U.S. Army four-year study funding -> /about", "Advisory board includes NCAA CMO, Army colonels, university physicians -> /about", "19 years research, millions invested without government grants -> /about", "Multiple patents issued, patents pending -> /about", "Intellig-EYES named after daughter Samira Elizabeth -> /about", "Zarreii education: BS Electronics Engineering, MS Controls Engineering, NYU neurology CME -> /about", "ECAT exempt from 510(k) -> /"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "designed and manufactured in the USA in an FDA-registered facility", "founded_year": "2003", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='axon-medical-technologies' AND approved AND profile IS NULL;
UPDATE companies SET description='B & H Sheet Metal operates from Asheville, North Carolina, where it has served Western North Carolina since 1976. The business is a second‑generation, family‑owned and operated fabrication shop that began with rolling, bending, punching, press brake forming, and shearing work.

The company provides full‑service custom sheet metal fabrication, working with steel, stainless steel, aluminum, copper, and galvanized materials. Its capabilities include rolling, bending, punching, press brake forming, shearing, and welding. No products are pre‑fabricated; each job—from custom chimney caps to stainless steel countertops—is built to order for both residential and commercial clients. The shop emphasizes that no job is too large or too small.

Customers range from homeowners and contractors to commercial builders across Western North Carolina. Typical projects include architectural metalwork such as chimney caps, countertops, and other custom metal designs for residential and commercial construction.

The firm highlights its warranty on workmanship, free consultations, and over four decades of experience as differentiators. It stresses competitive pricing and the ability to deliver parts when needed, reflecting a commitment to quality materials and customer experience passed down through the family.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Rolling", "Bending", "Punching", "Press brake forming", "Shearing", "Welding", "Custom sheet metal fabrication"], "industries": ["Residential construction", "Commercial construction", "Contractors", "Homeowners"], "materials": ["Steel", "Stainless steel", "Aluminum", "Copper", "Galvanized steel"], "equipment": ["Press brake"], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Second\u2011generation family\u2011owned and operated", "All products custom fabricated; no pre\u2011fabricated inventory", "Warranty on workmanship", "Free consultations", "Serving Western North Carolina since 1976"], "facts_used": ["Founded 1976 -> /", "Family-owned, second generation -> /", "Location Asheville, NC -> /", "Processes: rolling, bending, punching, press brake forming, shearing, welding -> /", "Materials: steel, stainless steel, aluminum, copper, galvanized -> /", "Serves residential and commercial clients -> /", "Custom fabrication, no pre-fabricated products -> /", "Warranty on workmanship -> /", "Free consultations -> /", "Over 40 years experience -> /", "Press brake forming -> /", "Serving Western North Carolina since 1976 -> /"], "company_type": "Contract manufacturer / job shop", "makes_products": "yes", "type_evidence": "B & H Sheet Metal specializes in metal fabrication and welding services in Asheville, NC.", "founded_year": "1976", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": ["Family-owned"]}'::jsonb, updated_at=now() WHERE slug='b-h-sheet-metal' AND approved AND profile IS NULL;
UPDATE companies SET description='B & L Scales, Inc. is based in Billings, Montana. Founded in 1976 by C. Leroy McBride, the company began as a one-man operation with McBride traveling the state on a Goldwing motorcycle, pulling a trailer of tools to service scales and equipment. The business remains family-owned; today it is operated by John and Nikki McFerran, with John continuing semi-annual service routes across Montana, Wyoming, and parts of Colorado while Nikki manages office operations.

The company sells and services a broad range of weighing equipment — from bench and floor scales to truck and rail scales — as well as meat processing machinery such as grinders, mixers, slicers, smokers, vacuum packers, and associated supplies. Its technicians are licensed in Montana and Wyoming to perform scale calibration, certification, repair, and placement-in-service reporting. The firm also provides equipment installation, repair, knife and grinder-plate sharpening, and acts as an authorized service representative for multiple brands.

Customers include meat processors, delis, ranchers, grocers, farmers’ markets, taxidermists, industrial plants, and individual buyers throughout Montana and Wyoming. The company participates in regional groups such as the Montana Meat Processors Association and the Montana Taxidermist Association.

